#!/usr/bin/env python3
"""
EKARUS ICD Server
=================
Listens for protobuf-encoded ``Request`` commands over TCP and returns ``Response`` messages.

Wire protocol
-------------
Each frame is a 4-byte big-endian unsigned length followed by that many bytes
of a serialised protobuf message.
- Client sends: Request
- Server responds: Response (with matching request_id)

Usage
-----
    python ekarusServer.py                 # live mode, port 5050
    python ekarusServer.py --sim           # simulator mode
    python ekarusServer.py -s -p 6000      # sim mode on port 6000
"""

import argparse
import logging
import os
import signal
import socket
import struct
import subprocess
import sys
import threading
from typing import Optional

from click import launch
import numpy as np

try:
    import daoEkarusICD_pb2 as icd  # generated by protoc
    from google.protobuf.timestamp_pb2 import Timestamp
    from daoEkarusShmMap import ShmParamMap
except ModuleNotFoundError:
    sys.exit(
        "ERROR: daoEkarusICD_pb2.py not found.\n"
        "Generate it with:\n"
        "  pip install grpcio-tools\n"
        "  python -m grpc_tools.protoc -I. --python_out=. daoEkarusICD.proto"
    )

LOG = logging.getLogger("ekarus")

# Lazily initialised on first use so import-time errors stay localised.
_shm_map: "ShmParamMap | None" = None


def _get_shm_map() -> "ShmParamMap":
    global _shm_map
    if _shm_map is None:
        _shm_map = ShmParamMap()
    return _shm_map


# ---------------------------------------------------------------------------
# Wire helpers
# ---------------------------------------------------------------------------

def _recv_exact(conn: socket.socket, n: int) -> bytes | None:
    """Read exactly *n* bytes from *conn*. Returns None on EOF."""
    buf = bytearray()
    while len(buf) < n:
        chunk = conn.recv(n - len(buf))
        if not chunk:
            return None
        buf.extend(chunk)
    return bytes(buf)


def recv_request(conn: socket.socket) -> Optional[icd.Request]:
    """Read one length-prefixed Request. Returns None on EOF or bad frame."""
    header = _recv_exact(conn, 4)
    if header is None:
        return None
    (length,) = struct.unpack(">I", header)
    if length == 0 or length > 1_048_576:
        LOG.warning("Suspicious frame length %d – dropping connection", length)
        return None
    data = _recv_exact(conn, length)
    if data is None:
        return None
    req = icd.Request()
    req.ParseFromString(data)
    return req


def send_response(conn: socket.socket, resp: icd.Response) -> None:
    """Send a length-prefixed Response."""
    data = resp.SerializeToString()
    conn.sendall(struct.pack(">I", len(data)) + data)


# ---------------------------------------------------------------------------
# Command dispatch
# ---------------------------------------------------------------------------

def handle_request(req: icd.Request, sim: bool) -> icd.Response:
    """Dispatch request and return a Response with matching request_id."""
    resp = icd.Response()
    resp.request_id = req.request_id
    resp.timestamp.GetCurrentTime()
    
    kind = req.WhichOneof("command")

    if kind is None:
        resp.status = icd.STATUS_ERROR
        resp.message = "Empty request (no command)"
        LOG.warning("[%s] Empty request ID %d", "SIM" if sim else "LIVE", req.request_id)
        return resp

    try:
        if kind == "loop":
            action = icd.CommandAction.Name(req.loop.command)
            LOG.info("[%s] Loop name=%r command=%s", "SIM" if sim else "LIVE", req.loop.name, action)
            if not sim:
                _do_loop(req.loop)
            resp.status = icd.STATUS_SUCCESS
            resp.message = f"Loop {req.loop.name} {action.lower()}"

        elif kind == "launch":
            mode = icd.LaunchMode.Name(req.launch.mode)
            LOG.info("[%s] Launch process=%r mode=%s", "SIM" if sim else "LIVE", req.launch.process_name, mode)
            if not sim:
                _do_launch(req.launch)
            resp.status = icd.STATUS_SUCCESS
            resp.message = f"Launched {req.launch.process_name}"

        elif kind == "set":
            param_name = req.set.param
            value_type = req.set.value.WhichOneof("data")
            LOG.info("[%s] Set param=%r type=%s", "SIM" if sim else "LIVE", param_name, value_type)
            if not sim:
                _do_set(req.set)
            resp.status = icd.STATUS_SUCCESS
            resp.message = f"Set {param_name}"

        elif kind == "get":
            param_name = req.get.param
            LOG.info("[%s] Get param=%r", "SIM" if sim else "LIVE", param_name)
            if not sim:
                value = _do_get(req.get)
            else:
                # Simulator returns a dummy scalar
                value = icd.Value()
                value.scalar_double = 42.0
            resp.value.CopyFrom(value)
            resp.status = icd.STATUS_SUCCESS
            resp.message = f"Retrieved {param_name}"

        elif kind == "telem":
            action = icd.TelemAction.Name(req.telem.action)
            channels = req.telem.channels if req.telem.channels else ["all"]
            LOG.info("[%s] Telem action=%s channels=%s rate=%d Hz", 
                    "SIM" if sim else "LIVE", action, channels, req.telem.rate_hz)
            if not sim:
                _do_telem(req.telem)
            resp.status = icd.STATUS_SUCCESS
            resp.message = f"Telemetry {action.lower()}"

        elif kind == "kill":
            LOG.info("[%s] Kill target=%r force=%s", "SIM" if sim else "LIVE", req.kill.target, req.kill.force)
            if not sim:
                _do_kill(req.kill)
            resp.status = icd.STATUS_SUCCESS
            resp.message = f"Killed {req.kill.target}"

        else:
            resp.status = icd.STATUS_INVALID
            resp.message = f"Unknown command: {kind}"
            LOG.warning("[%s] Unknown command %r", "SIM" if sim else "LIVE", kind)

    except Exception as e:
        resp.status = icd.STATUS_ERROR
        resp.message = f"Error: {str(e)}"
        LOG.error("[%s] Command failed: %s", "SIM" if sim else "LIVE", e, exc_info=True)

    return resp


# ---------------------------------------------------------------------------
# numpy <-> protobuf Value converters
# ---------------------------------------------------------------------------

def _numpy_to_value(arr: np.ndarray) -> icd.Value:
    """Convert a numpy array to a protobuf Value.

    Scalars (size==1) -> scalar_double / scalar_int
    1-D arrays        -> vector_double / vector_int
    2-D+ arrays       -> matrix_double / matrix_int  (higher dims flattened to rows)
    """
    value = icd.Value()
    is_float = np.issubdtype(arr.dtype, np.floating) or np.issubdtype(arr.dtype, np.complexfloating)
    flat = arr.flatten()

    if arr.size == 1:
        if is_float:
            value.scalar_double = float(flat[0])
        else:
            value.scalar_int = int(flat[0])
    elif arr.ndim == 1:
        if is_float:
            value.vector_double.values.extend(flat.astype(np.float64).tolist())
        else:
            value.vector_int.values.extend(flat.astype(np.int64).tolist())
    else:
        rows = arr.shape[0]
        cols = arr.size // rows
        if is_float:
            value.matrix_double.rows = rows
            value.matrix_double.cols = cols
            value.matrix_double.data.extend(flat.astype(np.float64).tolist())
        else:
            value.matrix_int.rows = rows
            value.matrix_int.cols = cols
            value.matrix_int.data.extend(flat.astype(np.int64).tolist())

    return value


def _value_to_numpy(value: icd.Value) -> np.ndarray:
    """Convert a protobuf Value to a numpy array."""
    kind = value.WhichOneof("data")
    if kind == "scalar_double":
        return np.array([value.scalar_double], dtype=np.float64)
    if kind == "scalar_int":
        return np.array([value.scalar_int], dtype=np.int64)
    if kind == "scalar_bool":
        return np.array([value.scalar_bool], dtype=np.bool_)
    if kind == "vector_double":
        return np.array(list(value.vector_double.values), dtype=np.float64)
    if kind == "vector_int":
        return np.array(list(value.vector_int.values), dtype=np.int64)
    if kind == "matrix_double":
        return np.array(list(value.matrix_double.data), dtype=np.float64).reshape(
            value.matrix_double.rows, value.matrix_double.cols
        )
    if kind == "matrix_int":
        return np.array(list(value.matrix_int.data), dtype=np.int64).reshape(
            value.matrix_int.rows, value.matrix_int.cols
        )
    raise ValueError(f"Cannot convert Value: no data field set")


