def _do_loop(loop: icd.Loop) -> None:
    """Execute loop command (open/close)."""
    LOG.debug("LIVE loop name=%s command=%s", loop.name, loop.command)
    # TODO: Implement actual loop control logic


def _do_launch(launch: icd.Launch) -> None:
    """Validate and execute a named launch script from $DAOROOT/bin."""
    daoroot = os.environ.get("DAOROOT")
    if not daoroot:
        raise RuntimeError("DAOROOT environment variable is not set")

    script_path = os.path.join(daoroot, "bin", launch.process_name)

    if not os.path.isfile(script_path):
        raise FileNotFoundError(
            f"Launch script not found: {script_path}"
        )
    if not os.access(script_path, os.X_OK):
        raise PermissionError(
            f"Launch script is not executable: {script_path}"
        )

    cmd = ["bash", script_path] + list(launch.args)

    env = os.environ.copy()
    if launch.env:
        env.update(launch.env)

    LOG.info("LIVE launch %s args=%s", launch.process_name, list(launch.args))
    subprocess.run(cmd, env=env, check=True)


def _do_set(s: icd.Set) -> None:
    """Set a parameter to a value (scalar, vector, or matrix)."""
    shm_map = _get_shm_map()

    if not shm_map.is_writable(s.param):
        raise ValueError(f"Parameter {s.param!r} is not writable or unknown")

    arr = _value_to_numpy(s.value)
    shm_path = shm_map.get_shm_path(s.param)
    LOG.debug("LIVE set %s shape=%s dtype=%s -> %s", s.param, arr.shape, arr.dtype, shm_path)
    shm_map.write_shm(s.param, arr)


def _do_get(g: icd.Get) -> icd.Value:
    """Retrieve a parameter value."""
    shm_map = _get_shm_map()

    if not shm_map.is_readable(g.param):
        raise ValueError(f"Parameter {g.param!r} is not readable or unknown")

    shm_path = shm_map.get_shm_path(g.param)
    LOG.debug("LIVE get %s -> %s", g.param, shm_path)
    arr = shm_map.read_shm(g.param)
    return _numpy_to_value(arr)


def _do_telem(t: icd.Telem) -> None:
    """Start or stop telemetry streaming."""
    channels_str = ", ".join(t.channels) if t.channels else "all"
    LOG.debug("LIVE telem action=%s channels=%s rate=%d Hz", 
             t.action, channels_str, t.rate_hz)
    # TODO: Implement telemetry streaming control


def _do_kill(k: icd.Kill) -> None:
    """Kill a process."""
    # Hammer now use daoEkarusCleanup.py to kill processes, but this is a placeholder for future logic.
    # use subproces to call daoEkarusCleanup.py with the target and force flag
